import { jsx as _jsx, jsxs as _jsxs } from "react/jsx-runtime";
import { describe, it, expect, vi, beforeEach } from "vitest";
import { screen, render, waitFor } from "@testing-library/react";
import { userEvent } from "@testing-library/user-event";
import "@testing-library/jest-dom/vitest";
import { AIFeedback } from "../AIFeedback";
import { RDSThemeProvider, THEME_MODES } from "../../../rdsThemeProvider";
import { CallistoThemeMap } from "../../../callistoTheme";
const mockOnFeedbackSubmit = vi.fn();
const mockOnFeedbackSelect = vi.fn();
const mockOnFeedbackClose = vi.fn();
const mockOnRefresh = vi.fn();
const mockOnCopy = vi.fn();
const mockOnDownload = vi.fn();
const renderWithTheme = (ui) => {
    return render(_jsx(RDSThemeProvider, { themeMap: CallistoThemeMap, themeMode: THEME_MODES.LIGHT, children: ui }));
};
describe("AIFeedback", () => {
    beforeEach(() => {
        vi.resetAllMocks();
    });
    it("should render learn more link when provided", () => {
        const learnMoreLink = "https://example.com/learn-more";
        renderWithTheme(_jsx(AIFeedback, { learnMoreLink: learnMoreLink, onFeedbackSubmit: mockOnFeedbackSubmit }));
        const link = screen.getByRole("link", { name: /learn more/i });
        expect(link).toBeInTheDocument();
        expect(link).toHaveAttribute("href", learnMoreLink);
        expect(link).toHaveAttribute("target", "_blank");
    });
    it("should not render learn more link when not provided", () => {
        renderWithTheme(_jsx(AIFeedback, { onFeedbackSubmit: mockOnFeedbackSubmit }));
        expect(screen.queryByRole("link", { name: /learn more/i })).not.toBeInTheDocument();
    });
    it("should open positive feedback popper when positive button is clicked", async () => {
        const user = userEvent.setup();
        renderWithTheme(_jsx(AIFeedback, { onFeedbackSubmit: mockOnFeedbackSubmit }));
        await user.click(screen.getByRole("button", { name: /positive feedback/i }));
        await waitFor(() => {
            expect(screen.getByText(/give feedback/i)).toBeInTheDocument();
            expect(screen.getByText(/Did this help you take action confidently\? We'd love to know what made the difference\./i)).toBeInTheDocument();
        });
    });
    it("should open negative feedback popper when negative button is clicked", async () => {
        const user = userEvent.setup();
        renderWithTheme(_jsx(AIFeedback, { onFeedbackSubmit: mockOnFeedbackSubmit }));
        await user.click(screen.getByRole("button", { name: /negative feedback/i }));
        await waitFor(() => {
            expect(screen.getByText(/give feedback/i)).toBeInTheDocument();
            expect(screen.getByText(/We're always working to improve\. Can you tell us what you didn't like about this experience\?/i)).toBeInTheDocument();
        });
    });
    it("should call onFeedbackSelect when feedback button is clicked", async () => {
        const user = userEvent.setup();
        renderWithTheme(_jsx(AIFeedback, { onFeedbackSelect: mockOnFeedbackSelect, onFeedbackSubmit: mockOnFeedbackSubmit }));
        await user.click(screen.getByRole("button", { name: /positive feedback/i }));
        expect(mockOnFeedbackSelect).toHaveBeenCalledWith("positive");
        await user.click(screen.getByRole("button", { name: /close/i }));
        await user.click(screen.getByRole("button", { name: /negative feedback/i }));
        expect(mockOnFeedbackSelect).toHaveBeenCalledWith("negative");
    });
    it("should render Try again button when onRefresh is provided", () => {
        renderWithTheme(_jsx(AIFeedback, { onFeedbackSubmit: mockOnFeedbackSubmit, onRefresh: mockOnRefresh }));
        expect(screen.getByRole("button", { name: /try again/i })).toBeInTheDocument();
    });
    it("should render Copy button when onCopy is provided", () => {
        renderWithTheme(_jsx(AIFeedback, { onCopy: mockOnCopy, onFeedbackSubmit: mockOnFeedbackSubmit }));
        expect(screen.getByRole("button", { name: /copy/i })).toBeInTheDocument();
    });
    it("should render Download button when onDownload is provided", () => {
        renderWithTheme(_jsx(AIFeedback, { onDownload: mockOnDownload, onFeedbackSubmit: mockOnFeedbackSubmit }));
        expect(screen.getByRole("button", { name: /download/i })).toBeInTheDocument();
    });
    it("should not render actions when no handlers are provided", () => {
        renderWithTheme(_jsx(AIFeedback, { onFeedbackSubmit: mockOnFeedbackSubmit }));
        expect(screen.queryByRole("button", { name: /copy/i })).not.toBeInTheDocument();
        expect(screen.queryByRole("button", { name: /copy/i })).not.toBeInTheDocument();
        expect(screen.queryByRole("button", { name: /download/i })).not.toBeInTheDocument();
    });
    it("should call onFeedbackClose when popper is closed", async () => {
        const user = userEvent.setup();
        renderWithTheme(_jsx(AIFeedback, { onFeedbackClose: mockOnFeedbackClose, onFeedbackSubmit: mockOnFeedbackSubmit }));
        await user.click(screen.getByRole("button", { name: /positive feedback/i }));
        await user.click(screen.getByRole("button", { name: /close/i }));
        expect(mockOnFeedbackClose).toHaveBeenCalled();
    });
    it("should call onFeedbackClose when clicking outside the component (ClickAwayListener)", async () => {
        const user = userEvent.setup();
        renderWithTheme(_jsxs("div", { children: [_jsx(AIFeedback, { onFeedbackClose: mockOnFeedbackClose, onFeedbackSubmit: mockOnFeedbackSubmit }), _jsx("div", { "data-testid": "outside-element", children: "Outside element" })] }));
        // Open the feedback popper
        await user.click(screen.getByRole("button", { name: /positive feedback/i }));
        await waitFor(() => {
            expect(screen.getByText(/give feedback/i)).toBeInTheDocument();
        });
        // Click outside the component
        await user.click(screen.getByTestId("outside-element"));
        // Verify onFeedbackClose was called
        expect(mockOnFeedbackClose).toHaveBeenCalled();
        // Verify the popper is closed
        await waitFor(() => {
            expect(screen.queryByText(/give feedback/i)).not.toBeInTheDocument();
        });
    });
    it("should submit feedback with selected options and comment", async () => {
        const user = userEvent.setup();
        mockOnFeedbackSubmit.mockResolvedValue(undefined);
        renderWithTheme(_jsx(AIFeedback, { onFeedbackSubmit: mockOnFeedbackSubmit }));
        await user.click(screen.getByRole("button", { name: /positive feedback/i }));
        await waitFor(() => {
            expect(screen.getByText(/helpful context/i)).toBeInTheDocument();
        });
        await user.click(screen.getByLabelText(/helpful context/i));
        await user.type(screen.getByPlaceholderText(/additional comments/i), "Great feature!");
        await user.click(screen.getByRole("button", { name: /^submit$/i }));
        await waitFor(() => {
            expect(mockOnFeedbackSubmit).toHaveBeenCalledWith("positive", ["helpfulContext"], "Great feature!");
        });
    });
});
